import { NextResponse } from "next/server";

// RFC 8414 discovery: MCP clients look here to find the authorize/token/register endpoints.
// The metadata is generated by the better-auth `mcp` plugin running in Convex.
export async function GET() {
  const res = await fetch(
    `${process.env.NEXT_PUBLIC_CONVEX_SITE_URL}/api/auth/.well-known/oauth-authorization-server`,
    { cache: "no-store" },
  );
  return NextResponse.json(await res.json(), {
    status: res.status,
    headers: { "Access-Control-Allow-Origin": "*" },
  });
}
